import{birthdayChance,collatz,harmonic,fibonacci,PHI,logistic,squareFourier,primeSpiral,montyOutcomes,complexProduct}from'./rare-math.js';
const C={blue:'#93b9fa',mint:'#b4f2d5',amber:'#efbd81',pink:'#ef96ba',purple:'#c1a0f5',white:'#edf2f6',muted:'#8e9eb3',grid:'#203046'};
const footer=(e,t)=>e.text(t,e.w/2,e.h-35,C.white,e.w<450?11:14,'center');
const cached=(e,key,make)=>{if(e.cacheKey!==key){e.cacheKey=key;e.cacheValue=make()}return e.cacheValue};
function sequence(e,series,max,colors,min=0){const left=42,top=35,width=e.w-68,height=e.h-115,xy=(i,y,n)=>[left+i/Math.max(1,n-1)*width,top+(max-y)/(max-min)*height];e.line([[left,top],[left,top+height],[left+width,top+height]],C.grid,1);e.text(max.toFixed(2),left-7,top+4,C.muted,10,'right');e.text(min.toFixed(1),left-7,top+height,C.muted,10,'right');series.forEach((values,k)=>e.line(values.map((v,i)=>xy(i,v,values.length)),colors[k],1.8));e.text('step',left+width,top+height+18,C.muted,11,'right');return xy}
export const rareRenderers={
birthday(){const n=this.v.n,p=birthdayChance(n),left=35,width=this.w-70,y=this.h*.48;this.line([[left,y],[left+width,y]],C.grid,14);this.line([[left,y],[left+width*p,y]],C.pink,14);this.line([[left+width*.5,y-25],[left+width*.5,y+25]],C.white,1,[3,4]);this.text('50%',left+width*.5,y+45,C.muted,12,'center');this.text(`${(p*100).toFixed(1)}%`,this.w/2,y-35,C.pink,30,'center');footer(this,`${n} people · ${n*(n-1)/2} pairs · probability of ≥1 match`)},
monty(){const cases=montyOutcomes(this.v.pick-1),cw=(this.w-55)/3,rh=(this.h-100)/3;cases.forEach((r,i)=>{for(let door=0;door<3;door++){const x=25+door*cw,y=24+i*rh,color=door===r.pick?C.blue:door===r.switched?C.mint:C.grid;this.poly([[x,y],[x+cw-10,y],[x+cw-10,y+rh-12],[x,y+rh-12]],color,.12);this.text(`${door+1}: ${door===r.prize?'PRIZE':door===r.opened?'opened':'empty'}`,x+cw/2-5,y+rh/2-3,door===r.prize?C.amber:C.muted,this.w<450?10:12,'center')}});footer(this,'Blue: stay · Mint: switch · Each row: one prize location')},
collatz(){const r=cached(this,`collatz:${this.v.seed}`,()=>collatz(this.v.seed));sequence(this,[r.values.map(v=>Math.log2(v))],Math.max(1,Math.log2(r.peak)),[C.purple]);this.text('log₂(value)',46,20,C.muted,11);footer(this,`${r.steps} steps · peak ${r.peak} · ${r.reachedOne?'reaches 1':'safety limit'}`)},
golden(){const{angle,n}=this.v,scale=Math.min(this.w-60,this.h-95)/2/Math.sqrt(n),cx=this.w/2,cy=(this.h-60)/2+12;for(let i=1;i<=n;i++){const t=i*angle*Math.PI/180,r=scale*Math.sqrt(i);this.dot(cx+r*Math.cos(t),cy+r*Math.sin(t),i%13===0?C.white:C.amber,Math.max(1.2,Math.min(3.2,scale*.8)))}footer(this,`${angle.toFixed(1)}° between seeds · ${n} seeds`)},
euler(){const n=this.v.n,r=Math.min(this.w*.27,(this.h-105)*.33),cx=this.w*.45,cy=(this.h-65)/2+30,shift=[r*.65,-r*.65],front=Array.from({length:n},(_,i)=>{const t=i/n*2*Math.PI-Math.PI/2;return[cx+r*Math.cos(t),cy+r*.64*Math.sin(t)]}),back=front.map(p=>[p[0]+shift[0],p[1]+shift[1]]);this.poly(back,C.muted,.035);front.forEach((p,i)=>this.line([p,back[i]],C.mint,1.3));this.poly(front,C.mint,.1);[...front,...back].forEach(p=>this.dot(...p,C.amber,3));footer(this,`V ${2*n} − E ${3*n} + F ${n+2} = 2`)},
harmonic(){const n=this.v.n,values=cached(this,`harmonic:${n}`,()=>{let sum=0;return Array.from({length:n},(_,i)=>sum+=1/(i+1))});sequence(this,[values,Array(n).fill(2)],Math.max(2.3,values.at(-1)*1.1),[C.amber,C.muted]);footer(this,`H${n} = ${harmonic(n).toFixed(4)} · gray line: geometric-series limit 2`)},
primes(){const points=cached(this,`primes:${this.v.n}`,()=>primeSpiral(this.v.n)),extent=Math.ceil(Math.sqrt(this.v.n)/2),unit=Math.min(this.w-55,this.h-100)/(extent*2+2),cx=this.w/2,cy=(this.h-65)/2+10;for(const p of points)this.dot(cx+p.x*unit,cy-p.y*unit,p.prime?C.mint:C.grid,Math.max(.8,unit*.22));footer(this,`${points.filter(p=>p.prime).length} primes highlighted · 1 is not prime`)},
pigeonhole(){const{rooms,visitors}=this.v,cols=rooms<=4?rooms:4,rows=Math.ceil(rooms/cols),cw=(this.w-50)/cols,ch=Math.min(110,(this.h-105)/rows);for(let room=0;room<rooms;room++){const x=25+(room%cols)*cw,y=30+Math.floor(room/cols)*ch;this.poly([[x,y],[x+cw-8,y],[x+cw-8,y+ch-12],[x,y+ch-12]],C.purple,.05);const count=Math.floor(visitors/rooms)+(room<visitors%rooms?1:0);this.text(String(count),x+(cw-8)/2,y+ch*.55,C.mint,Math.max(16,Math.min(27,ch*.4)),'center')}footer(this,`Some room must contain at least ${Math.ceil(visitors/rooms)}`)},
fibonacci(){const n=this.v.n,f=fibonacci(n+1),ratios=Array.from({length:n-1},(_,i)=>f[i+3]/f[i+2]);sequence(this,[ratios,Array(ratios.length).fill(PHI)],2.1,[C.amber,C.mint],1.3);footer(this,`${f[n+1]}/${f[n]} = ${(f[n+1]/f[n]).toFixed(6)} · φ ≈ ${PHI.toFixed(6)}`)},
logistic(){const{r,x}=this.v;sequence(this,[logistic(r,x,60),logistic(r,x+.0001,60)],1,[C.blue,C.pink]);footer(this,'Blue start x · Pink start x + 0.0001 · deterministic rules')},
complex(){const{angle,scale}=this.v,xy=this.chart(-5,5,-5,5),out=complexProduct(2,1,scale,angle);this.arrow(xy(0,0),xy(2,1),C.blue);this.arrow(xy(0,0),xy(...out),C.mint);this.dot(...xy(...out),C.amber,5);footer(this,`Turn ${angle}° · length ×${scale.toFixed(1)} · i² = −1`)},
fourier(){const terms=this.v.terms,xy=this.chart(-Math.PI,Math.PI,-1.7,1.7),pts=[];for(let i=0;i<=360;i++){const x=-Math.PI+i/360*Math.PI*2;pts.push(xy(x,squareFourier(x,terms)))}this.line([xy(-Math.PI,-1),xy(0,-1),xy(0,1),xy(Math.PI,1)],C.muted,1,[4,5]);this.line(pts,C.mint,2.5);footer(this,`${terms} odd harmonics · sum in mint · target in gray`)}
};
